# Reusing helper functions
import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1 
    return reduce(lcm, numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    if n < 2:
        return 0

    count = 0
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_A = list_lcm(A_k)
        gcd_B = list_gcd(B_k)

        if lcm_A == gcd_B:
            count += 1
    return count

# --- Systematic search for n=5 ---
min_p_5 = float('inf')
max_p_5 = 0

# Limit a5 to 20. This is O(20^5) ~ 3.2 million iterations, which should be feasible.
SEARCH_LIMIT_N5 = 20
print(f"Starting systematic search for n=5 up to a5={SEARCH_LIMIT_N5}...")

import time
start_time = time.time()

for a5 in range(1, SEARCH_LIMIT_N5 + 1):
    for a4 in range(1, a5):
        for a3 in range(1, a4):
            for a2 in range(1, a3):
                for a1 in range(1, a2):
                    seq = (a1, a2, a3, a4, a5)
                    p = count_good_partitions(seq)

                    # Only update min/max
                    min_p_5 = min(min_p_5, p)
                    max_p_5 = max(max_p_5, p)

end_time = time.time()
print(f"Search completed in {end_time - start_time:.2f} seconds.")
print(f"\nSummary n=5 (Search limit a5 <= {SEARCH_LIMIT_N5}):")
print(f"Minimum P found: {min_p_5}")
print(f"Maximum P found: {max_p_5}")

import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a*b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# Test sequence (1, 2, 3, 6) for n=4
a = [1, 2, 3, 6]
n = len(a)
print(f"Sequence: {a}, n={n}")
good_partitions = []

for k in range(1, n):
    A_k = a[:k]
    B_k = a[k:]

    lcm_A = list_lcm(A_k)
    gcd_B = list_gcd(B_k)

    is_good = lcm_A == gcd_B
    good_partitions.append(is_good)

    print(f"k={k}: LCM(A_k)={lcm_A}, GCD(B_k)={gcd_B}. Good? {is_good}")

print(f"Total good partitions P: {sum(good_partitions)}")

